assert.equal(dlq.messages[0].reasonCode, 'MAX_RETRIES_EXCEEDED');
assert.equal(lockManager.held.size, 0);

await lockManager.tryLease({ resourceKey: 'o3', ttlMs: 5000 });
const resBusy = await consumer.consumeOrderEvent({ eventId: 'e3', orderId: 'o3', retryCount: 0 });
